"use strict";exports.formatDate=function(t,e="YYYY-MM-DD HH:mm"){const r=new Date(t),a=r.getFullYear(),n=String(r.getMonth()+1).padStart(2,"0"),g=String(r.getDate()).padStart(2,"0"),p=String(r.getHours()).padStart(2,"0"),S=String(r.getMinutes()).padStart(2,"0"),c=String(r.getSeconds()).padStart(2,"0");return e.replace("YYYY",String(a)).replace("MM",n).replace("DD",g).replace("HH",p).replace("mm",S).replace("ss",c)};
